import { promises as fs } from 'node:fs';for(const p of ['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await append('scripts/build.mjs','v24-3-build-patch.txt','V24.3 Turkish/English article voice');await append('assets/atlas.css','v24-3-css-patch.txt','V24.3 Turkish voice controls');await fs.copyFile('article-reader.js','assets/article-reader.js');console.log('V24.3 kuruldu: Türkçe/İngilizce sesli okuma ve makale kayma-kırpılma düzeltmesi eklendi.');
